import os
from datetime import datetime

def span_days(records, path):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    records_dict = {}
    for record in records:
        date, label = record.split('=', 1)
        date = datetime.strptime(date.strip(), '%Y-%m-%d')
        if label not in records_dict:
            records_dict[label] = [date]
        else:
            records_dict[label].append(date)

    for label in sorted(records_dict.keys()):
        dates = records_dict[label]
        earliest = min(dates)
        latest = max(dates)
        days = (latest - earliest).days
        print(f"{label}:{days}\n", end='', file=open(path, 'a', encoding='utf-8'))
